#!/usr/bin/env node
/**
 * apply-pwa.js — make the website installable as a phone app (Chrome / Edge / Android, and Add-to-Home-Screen on iPhone).
 *
 *   Run from your project folder (the one containing package.json and public/):
 *       node apply-pwa.js
 *
 * It adds: the app manifest, real PNG app icons, a service worker, an offline page, an "Install app" pop-up banner,
 * "Install app" buttons in the public header and the dashboard top bar, and the needed tags on every page.
 * Safe to run more than once. Commit first so you can undo with:  git restore .
 */
const fs = require('fs');
const path = require('path');

const ROOT = process.cwd();
const PUB = path.join(ROOT, 'public');
if (!fs.existsSync(PUB)) { console.error('Run this from your project folder (it must contain a "public" folder).'); process.exit(1); }

const ICONS = {"icon-192": "", "icon-512": "", "icon-maskable-512": "", "apple-touch-icon": ""};
const FILES = {"pwa.js": "/* Install-as-app support: service worker + an \"Install app\" pop-up and buttons on every page. */\nconst HAS_ICONS = __HAS_ICONS__;\nconst ic = (n) => (HAS_ICONS ? `<i data-icon=\"${n}\"></i>` : '');\nif (HAS_ICONS) import('./icons.js').catch(() => {});\n\nif ('serviceWorker' in navigator && (location.protocol === 'https:' || location.hostname === 'localhost')) {\n  window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));\n}\n\nconst standalone = () => window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;\nconst isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);\nconst KEY = 'pwa-banner-hidden-until';\nlet deferred = null;\n\nfunction hideBannerFor(days) { try { localStorage.setItem(KEY, String(Date.now() + days * 864e5)); } catch { /* private mode */ } document.querySelector('.install-banner')?.remove(); }\nconst bannerAllowed = () => { try { return Date.now() > Number(localStorage.getItem(KEY) || 0); } catch { return true; } };\n\nfunction help() {\n  const wrap = document.createElement('div');\n  wrap.className = 'modal-backdrop';\n  const steps = isIOS\n    ? `<ol><li>Open this page in <b>Safari</b>.</li><li>Tap the <b>Share</b> button ${ic('share')} at the bottom.</li><li>Scroll and tap <b>Add to Home Screen</b>, then <b>Add</b>.</li></ol>`\n    : `<ol><li>Open this page in <b>Chrome</b> (or Edge).</li><li>Tap the <b>\u22ee menu</b> at the top right.</li><li>Tap <b>Install app</b> (or <b>Add to Home screen</b>).</li></ol><p class=\"text-muted\" style=\"font-size:.85rem;\">If you do not see it, reload the page once and try again.</p>`;\n  wrap.innerHTML = `<div class=\"modal\" style=\"max-width:420px;width:94%;\"><div class=\"modal-head\"><h3>${ic('smartphone')} Install the app</h3><button class=\"btn btn-ghost btn-sm\" data-x aria-label=\"Close\">&times;</button></div>\n    <div class=\"modal-body\"><p>Put FUGOBPANS on your phone like a normal app. It opens full screen and needs no app store.</p>${steps}<button class=\"btn btn-primary btn-block\" data-x>Got it</button></div></div>`;\n  document.body.appendChild(wrap);\n  wrap.addEventListener('click', (e) => { if (e.target === wrap || e.target.closest('[data-x]')) wrap.remove(); });\n}\n\nasync function install() {\n  if (deferred) { deferred.prompt(); try { await deferred.userChoice; } catch { /* ignore */ } deferred = null; document.querySelector('.install-banner')?.remove(); return; }\n  help();\n}\n\nfunction showBanner() {\n  if (standalone() || !bannerAllowed() || document.querySelector('.install-banner')) return;\n  const b = document.createElement('div');\n  b.className = 'install-banner'; b.setAttribute('role', 'dialog'); b.setAttribute('aria-label', 'Install the app');\n  b.innerHTML = `<img src=\"/assets/icons/icon-192.png\" width=\"44\" height=\"44\" alt=\"\" /><div class=\"ib-text\"><strong>Install FUGOBPANS</strong><span>${isIOS ? 'Add it to your home screen.' : 'Get the app on your phone.'}</span></div>\n    <button type=\"button\" class=\"btn btn-accent btn-sm\" data-go>${isIOS ? 'Show me how' : 'Install'}</button><button type=\"button\" class=\"btn btn-ghost btn-sm\" data-no aria-label=\"Not now\">&times;</button>`;\n  document.body.appendChild(b);\n  b.querySelector('[data-go]').addEventListener('click', install);\n  b.querySelector('[data-no]').addEventListener('click', () => hideBannerFor(7));\n}\n\nwindow.addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); deferred = e; setTimeout(showBanner, 1500); });\nwindow.addEventListener('appinstalled', () => { deferred = null; document.querySelectorAll('[data-install-app], .install-banner').forEach((n) => n.remove()); });\n\nfunction mount() {\n  if (standalone()) return;\n  let buttons = [...document.querySelectorAll('[data-install-app]')];\n  if (!buttons.length) {\n    const f = document.createElement('button');\n    f.type = 'button'; f.setAttribute('data-install-app', ''); f.className = 'install-fab';\n    document.body.appendChild(f); buttons = [f];\n  }\n  buttons.forEach((b) => {\n    if (b.dataset.ready) return; b.dataset.ready = '1';\n    if (!b.innerHTML.trim()) b.innerHTML = `${ic('download')} <span>Install app</span>`;\n    b.addEventListener('click', install);\n  });\n  if (isIOS && !standalone()) setTimeout(showBanner, 2500); // iPhone has no install event, so show the steps once\n}\nif (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mount); else mount();\nwindow.addEventListener('load', () => setTimeout(mount, 300));\n", "sw.js": "/* Service worker: makes the site installable and shows a friendly page when offline.\n * It NEVER caches API calls, logins or payments: those always go to the network. */\nconst VERSION = 'fugobpans-v2';\nconst SHELL = ['/offline.html', '/assets/icons/icon-192.png'];\nconst PUBLIC_PAGES = ['/', '/index.html', '/about.html', '/classes.html', '/admissions.html', '/contact.html', '/announcements.html', '/reviews.html', '/students.html', '/parents.html', '/register.html'];\n\nself.addEventListener('install', (e) => { e.waitUntil(caches.open(VERSION).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting())); });\nself.addEventListener('activate', (e) => { e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim())); });\n\nself.addEventListener('fetch', (e) => {\n  const req = e.request; const url = new URL(req.url);\n  if (req.method !== 'GET' || url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return; // network only\n  if (req.mode === 'navigate') {\n    const isPublic = PUBLIC_PAGES.includes(url.pathname);\n    e.respondWith(fetch(req).then((res) => { if (isPublic && res.ok) { const copy = res.clone(); caches.open(VERSION).then((c) => c.put(req, copy)); } return res; })\n      .catch(async () => (isPublic && (await caches.match(req))) || caches.match('/offline.html')));\n    return;\n  }\n  if (url.pathname.startsWith('/assets/')) { // show the saved copy fast, refresh it in the background\n    e.respondWith(caches.open(VERSION).then(async (c) => { const hit = await c.match(req); const net = fetch(req).then((r) => { if (r.ok) c.put(req, r.clone()); return r; }).catch(() => hit); return hit || net; }));\n  }\n});\n", "offline.html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Offline | FUGOBPANS</title>\n<style>body{margin:0;font-family:system-ui,Arial,sans-serif;display:flex;min-height:100vh;align-items:center;justify-content:center;text-align:center;padding:24px;background:#f5f7fb;color:#12203d}\nbutton{background:#12203d;color:#fff;border:0;border-radius:10px;padding:12px 22px;font-size:1rem;font-weight:600;cursor:pointer}p{color:#5b6477}</style></head>\n<body><div><img src=\"/assets/icons/icon-192.png\" width=\"96\" height=\"96\" alt=\"\" style=\"border-radius:20px\"><h1>You are offline</h1>\n<p>Check your phone's internet connection, then try again.</p><button onclick=\"location.reload()\">Try again</button></div></body></html>\n", "manifest": "{\n  \"name\": \"FUGOBPANS School\",\n  \"short_name\": \"FUGOBPANS\",\n  \"description\": \"Register, pay fees, check results and school news on your phone.\",\n  \"id\": \"/\",\n  \"start_url\": \"/index.html\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#12203d\",\n  \"theme_color\": \"#12203d\",\n  \"lang\": \"en\",\n  \"icons\": [\n    { \"src\": \"/assets/icons/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/assets/icons/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/assets/icons/icon-maskable-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\" }\n  ]\n}\n", "css": "\n/* ---- Install app ---- */\n.install-fab { position: fixed; left: 14px; bottom: 14px; z-index: 900; display: inline-flex; align-items: center; gap: 8px; padding: 10px 16px; border: 0; border-radius: 999px;\n  background: #12203d; color: #fff; font-weight: 600; font-size: .9rem; box-shadow: 0 6px 18px rgba(13,23,48,.35); cursor: pointer; }\n.install-fab:hover { background: #2743a8; }\n.install-btn { display: inline-flex; align-items: center; gap: 6px; }\n.install-banner { position: fixed; left: 12px; right: 12px; bottom: 12px; z-index: 1000; display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 16px;\n  background: #fff; color: #12203d; box-shadow: 0 10px 34px rgba(13,23,48,.35); max-width: 520px; margin: 0 auto; }\n.install-banner img { border-radius: 10px; flex: none; }\n.install-banner .ib-text { flex: 1; display: flex; flex-direction: column; font-size: .85rem; line-height: 1.25; }\n.install-banner .ib-text strong { font-size: .95rem; }\n@media (display-mode: standalone) { .install-fab, .install-banner, [data-install-app] { display: none !important; } }\n"};

const write = (rel, data, enc) => { const f = path.join(PUB, rel); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, data, enc); };
const HAS_ICONS = fs.existsSync(path.join(PUB, 'assets', 'js', 'icons.js')); // only use the icon library if apply-icons.js was run

for (const [name, b64] of Object.entries(ICONS)) write(`assets/icons/${name}.png`, Buffer.from(b64, 'base64'));
write('manifest.webmanifest', FILES.manifest);
write('sw.js', FILES['sw.js']);
write('offline.html', FILES['offline.html']);
write('assets/js/pwa.js', FILES['pwa.js'].replace('__HAS_ICONS__', String(HAS_ICONS)));
console.log(`Wrote manifest, service worker, offline page, 4 app icons and pwa.js (icon library ${HAS_ICONS ? 'found' : 'not found: plain text buttons'})`);

const cssPath = path.join(PUB, 'assets', 'css', 'style.css');
if (fs.existsSync(cssPath) && !fs.readFileSync(cssPath, 'utf8').includes('/* ---- Install app ---- */')) { fs.appendFileSync(cssPath, FILES.css); console.log('Added install styles to style.css'); }

const HEAD = `<link rel="manifest" href="/manifest.webmanifest" />
<meta name="theme-color" content="#12203d" />
<meta name="mobile-web-app-capable" content="yes" /><meta name="apple-mobile-web-app-capable" content="yes" /><meta name="apple-mobile-web-app-title" content="FUGOBPANS" />
<link rel="apple-touch-icon" href="/assets/icons/apple-touch-icon.png" />`;

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) { if (e.name !== 'node_modules') walk(p, out); } else if (e.name.endsWith('.html')) out.push(p);
  }
  return out;
}
let pages = 0, buttons = 0;
for (const file of walk(PUB)) {
  if (file.endsWith('offline.html')) continue;
  let s = fs.readFileSync(file, 'utf8'); const before = s;
  if (!s.includes('manifest.webmanifest') && s.includes('</head>')) s = s.replace('</head>', `${HEAD}\n</head>`);
  if (!s.includes('/assets/js/pwa.js') && s.includes('</body>')) s = s.replace('</body>', '<script type="module" src="/assets/js/pwa.js"></script>\n</body>');
  if (s.includes('id="notifBell"') && !s.includes('data-install-app')) { s = s.replace('<button id="notifBell"', '<button type="button" data-install-app class="btn btn-outline btn-sm install-btn"></button>\n        <button id="notifBell"'); buttons++; }
  if (s !== before) { fs.writeFileSync(file, s, 'utf8'); pages++; }
}
console.log(`Updated ${pages} pages (${buttons} dashboard top bars got an Install button)`);

// public website header + menu
const pl = path.join(PUB, 'assets', 'js', 'public-layout.js');
if (fs.existsSync(pl)) {
  let s = fs.readFileSync(pl, 'utf8');
  if (!s.includes('data-install-app')) {
    const a = s.replace('<div class="site-header-actions">\n          <a href="/login.html"', '<div class="site-header-actions">\n          <button type="button" data-install-app class="btn btn-ghost btn-sm install-btn"></button>\n          <a href="/login.html"');
    const b = a.replace('<div style="display:flex;flex-direction:column;gap:10px;margin-top:22px;">\n        <a href="/login.html"', '<div style="display:flex;flex-direction:column;gap:10px;margin-top:22px;">\n        <button type="button" data-install-app class="btn btn-primary btn-block install-btn"></button>\n        <a href="/login.html"');
    if (b !== s) { fs.writeFileSync(pl, b, 'utf8'); console.log('Added Install buttons to the public header and menu'); }
  }
}

// Firebase hosting: always fetch the newest service worker
const fb = path.join(ROOT, 'firebase.json');
if (fs.existsSync(fb)) {
  try {
    const j = JSON.parse(fs.readFileSync(fb, 'utf8'));
    j.hosting = j.hosting || {}; j.hosting.headers = j.hosting.headers || [];
    if (!j.hosting.headers.some((h) => h.source === '/sw.js')) {
      j.hosting.headers.unshift({ source: '/sw.js', headers: [{ key: 'Cache-Control', value: 'no-cache, max-age=0' }, { key: 'Service-Worker-Allowed', value: '/' }] });
      fs.writeFileSync(fb, JSON.stringify(j, null, 2)); console.log('Updated firebase.json for the service worker');
    }
  } catch { /* leave firebase.json alone */ }
}

console.log(`
Done. Next:
  1. git add public firebase.json
  2. git commit -m "Make the site installable as an app"
  3. git push origin main
  4. When Render shows Live, open the site in Chrome on your phone (https), reload once, then:
     tap the Install banner, or the Install app button, or Chrome menu (three dots) > Install app.`);